describe('Modal with Video - Pause on Close', () => {
  beforeEach(() => {
    cy.visit('/modal-video');
  });

  it('should pause video when modal is closed', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="video-modal"]').should('be.visible');

    // Verify video is playing
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').then(($video) => {
      expect($video[0].paused).to.be.false;
    });

    // Close the modal
    cy.get('[data-testid="close-modal-button"]').click();
    cy.get('[data-testid="video-modal"]').should('not.exist');

    // Verify video is paused after closing
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').then(($video) => {
      expect($video[0].paused).to.be.true;
    });
  });

  it('should not pause video when modal is interacted with', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();
    cy.get('[data-testid="video-modal"]').should('be.visible');

    // Verify video is playing
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').then(($video) => {
      expect($video[0].paused).to.be.false;
    });

    // Interact with video controls (e. pause)
    cy.get('[data-testid="pause-button"]').click();
    cy.get('[data-testid="video-player"]').then(($video) => {
      expect($video[0].paused).to.be.true;
    });

    // Close the modal
    cy.get('[data-testid="close-modal-button"]').click();
    cy.get('[data-testid="video-modal"]').should('not.exist');

    // Verify video remains paused after closing
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').then(($video) => {
      expect($video[0].paused).to.be.true;
    });
  });
});
